import { type } from '../../../shared/utility/utilityHelpers';
export const ActionTypes = {
  GET_FEEDBACK_LIST: type("[FEEDBACK] Feedback list "),
  GET_FEEDBACK_LIST_SUCCESS: type("[FEEDBACK] Feedback List Success"),
  GET_FEEDBACK_LIST_FAIL: type("[FEEDBACK] Feedback list Fail")
}; // FEEDBACK LIST

export class FeedbackListAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_FEEDBACK_LIST;
  }

}
export class FeedbackListSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_FEEDBACK_LIST_SUCCESS;
  }

}
export class FeedbackListFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.GET_FEEDBACK_LIST_FAIL;
  }

}
